50:     /**
51:      * @notice Internal method to delegate execution to another contract
52:      * @dev It returns to the external caller whatever the implementation returns or forwards reverts
53:      * @param callee The contract to delegatecall
54:      * @param data The raw data to delegatecall
55:      */
56:     function delegateTo(address callee, bytes memory data) internal {
57:         (bool success, bytes memory returnData) = callee.delegatecall(data);
58:         assembly {
59:             if eq(success, 0) {
60:                 revert(add(returnData, 0x20), returndatasize())
61:             }
62:         }
63:     }
